package main

import (
	"image"
	"image/color"
	"image/png"
	"os"
)

func main() {
	// 100x50 image
	img := image.NewRGBA(image.Rect(0, 0, 100, 50))
	for y := 0; y < 50; y++ {
		for x := 0; x < 100; x++ {
			img.Set(x, y, color.RGBA{uint8(x * 2), uint8(y * 4), 100, 255})
		}
	}
	f, _ := os.Create("/tmp/imgtest/rect100x50.png")
	defer f.Close()
	png.Encode(f, img)
}
EOF
cd /tmp/imgtest && go run make_rect.go"}

