{"command":"mkdir -p /tmp/imgtest && cat <<'EOF' > /tmp/imgtest/make_various.go
package main

import (
	"fmt"
	"image"
	"image/color"
	"image/png"
	"os"
)

func makeImg(w, h int, filename string) {
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			img.Set(x, y, color.RGBA{uint8(x), uint8(y), 100, 255})
		}
	}
	f, _ := os.Create(filename)
	defer f.Close()
	png.Encode(f, img)
}

func main() {
	sizes := [][2]int{{100, 100}, {200, 100}, {100, 200}, {50, 50}, {30, 80}, {80, 30}}
	for _, sz := range sizes {
		fname := fmt.Sprintf("/tmp/imgtest/img_%dx%d.png", sz[0], sz[1])
		makeImg(sz[0], sz[1], fname)
	}
}
EOF
cd /tmp/imgtest && go run make_various.go"}

