package main

import (
	"image"
	"image/color"
	"io"
)

func init() {
	image.RegisterFormat("bmp", "BM", decodeBMP, decodeBMPConfig)
}

func decodeBMPConfig(r io.Reader) (image.Config, error) {
	header := make([]byte, 26)
	if _, err := io.ReadFull(r, header); err != nil {
		return image.Config{}, err
	}
	if header[0] != 'B' || header[1] != 'M' {
		return image.Config{}, image.ErrFormat
	}
	w := int(int32(header[18]) | int32(header[19])<<8 | int32(header[20])<<16 | int32(header[21])<<24)
	h := int(int32(header[22]) | int32(header[23])<<8 | int32(header[24])<<16 | int32(header[25])<<24)
	if h < 0 {
		h = -h
	}
	return image.Config{
		ColorModel: color.RGBAModel,
		Width:      w,
		Height:     h,
	}, nil
}

func decodeBMP(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	if len(data) < 54 || data[0] != 'B' || data[1] != 'M' {
		return nil, image.ErrFormat
	}
	offset := int(uint32(data[10]) | uint32(data[11])<<8 | uint32(data[12])<<16 | uint32(data[13])<<24)
	w := int(int32(data[18]) | int32(data[19])<<8 | int32(data[20])<<16 | int32(data[21])<<24)
	h := int(int32(data[22]) | int32(data[23])<<8 | int32(data[24])<<16 | int32(data[25])<<24)
	bpp := int(uint16(data[28]) | uint16(data[29])<<8)

	topDown := false
	if h < 0 {
		h = -h
		topDown = true
	}

	img := image.NewRGBA(image.Rect(0, 0, w, h))

	if bpp == 24 || bpp == 32 {
		bytesPerPixel := bpp / 8
		rowSize := ((w*bytesPerPixel + 3) / 4) * 4
		for y := 0; y < h; y++ {
			rowY := y
			if !topDown {
				rowY = h - 1 - y
			}
			rowStart := offset + y*rowSize
			if rowStart >= len(data) {
				break
			}
			for x := 0; x < w; x++ {
				pxStart := rowStart + x*bytesPerPixel
				if pxStart+2 >= len(data) {
					break
				}
				b := data[pxStart]
				g := data[pxStart+1]
				r := data[pxStart+2]
				a := byte(255)
				if bytesPerPixel == 4 && pxStart+3 < len(data) {
					a = data[pxStart+3]
				}
				img.SetRGBA(x, rowY, color.RGBA{r, g, b, a})
			}
		}
	}
	return img, nil
}
