{"command":"cat <<'EOF' > ansimage.go
package main

import (
	"fmt"
	"image"
	"image/color"
	"image/draw"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"math"
	"strings"

	"github.com/lucasb-eyer/go-colorful"
)

type ANSImage struct {
	img           image.Image
	scaleMethod   int
	ditheringMode int
	matteColor    color.Color
	noBg          bool
	width         int
	height        int
}

func bilinear(c00, c10, c01, c11, dx, dy float64) float64 {
	top := c00*(1.0-dx) + c10*dx
	bot := c01*(1.0-dx) + c11*dx
	return top*(1.0-dy) + bot*dy
}

func scaleBilinear(src image.Image, width, height int) image.Image {
	if width <= 0 || height <= 0 {
		return image.NewRGBA(image.Rect(0, 0, 0, 0))
	}
	srcBounds := src.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()
	dst := image.NewRGBA(image.Rect(0, 0, width, height))

	xScale := float64(srcW) / float64(width)
	yScale := float64(srcH) / float64(height)

	for y := 0; y < height; y++ {
		srcY := (float64(y)+0.5)*yScale - 0.5
		if srcY < 0 {
			srcY = 0
		}
		if srcY >= float64(srcH-1) {
			srcY = float64(srcH - 1)
		}
		y0 := int(srcY)
		y1 := y0 + 1
		if y1 >= srcH {
			y1 = srcH - 1
		}
		dy := srcY - float64(y0)

		for x := 0; x < width; x++ {
			srcX := (float64(x)+0.5)*xScale - 0.5
			if srcX < 0 {
				srcX = 0
			}
			if srcX >= float64(srcW-1) {
				srcX = float64(srcW - 1)
			}
			x0 := int(srcX)
			x1 := x0 + 1
			if x1 >= srcW {
				x1 = srcW - 1
			}
			dx := srcX - float64(x0)

			c00 := src.At(srcBounds.Min.X+x0, srcBounds.Min.Y+y0)
			c10 := src.At(srcBounds.Min.X+x1, srcBounds.Min.Y+y0)
			c01 := src.At(srcBounds.Min.X+x0, srcBounds.Min.Y+y1)
			c11 := src.At(srcBounds.Min.X+x1, srcBounds.Min.Y+y1)

			r00, g00, b00, a00 := c00.RGBA()
			r10, g10, b10, a10 := c10.RGBA()
			r01, g01, b01, a01 := c01.RGBA()
			r11, g11, b11, a11 := c11.RGBA()

			r := bilinear(float64(r00), float64(r10), float64(r01), float64(r11), dx, dy)
			g := bilinear(float64(g00), float64(g10), float64(g01), float64(g11), dx, dy)
			b := bilinear(float64(b00), float64(b10), float64(b01), float64(b11), dx, dy)
			a := bilinear(float64(a00), float64(a10), float64(a01), float64(a11), dx, dy)

			dst.SetRGBA(x, y, color.RGBA{
				R: uint8(r / 257.0),
				G: uint8(g / 257.0),
				B: uint8(b / 257.0),
				A: uint8(a / 257.0),
			})
		}
	}
	return dst
}

func cropCenter(src image.Image, cropW, cropH int) image.Image {
	bounds := src.Bounds()
	w := bounds.Dx()
	h := bounds.Dy()

	startX := (w - cropW) / 2
	startY := (h - cropH) / 2

	dst := image.NewRGBA(image.Rect(0, 0, cropW, cropH))
	draw.Draw(dst, dst.Bounds(), src, image.Pt(bounds.Min.X+startX, bounds.Min.Y+startY), draw.Src)
	return dst
}

func NewScaledFromImage(src image.Image, scaleMethod int, termCols, termRows int, matteColor color.Color, ditheringMode int, noBg bool) (*ANSImage, error) {
	if src == nil {
		return nil, fmt.Errorf("ANSImage: image is nil")
	}

	srcBounds := src.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()

	if srcW < 2 || srcH < 2 {
		return nil, fmt.Errorf("ANSImage: height or width must be >=2")
	}

	maxPixelW := termCols
	maxPixelH := termRows * 2

	var targetW, targetH int

	switch scaleMethod {
	case 0: // Resize
		targetW = maxPixelW
		targetH = maxPixelH

	case 1: // Fill
		scaleW := float64(maxPixelW) / float64(srcW)
		scaleH := float64(maxPixelH) / float64(srcH)
		scale := math.Max(scaleW, scaleH)

		scaledW := int(math.Round(float64(srcW) * scale))
		scaledH := int(math.Round(float64(srcH) * scale))

		tempImg := scaleBilinear(src, scaledW, scaledH)
		scaledImg := cropCenter(tempImg, maxPixelW, maxPixelH)
		return &ANSImage{
			img:           scaledImg,
			scaleMethod:   scaleMethod,
			ditheringMode: ditheringMode,
			matteColor:    matteColor,
			noBg:          noBg,
			width:         maxPixelW,
			height:        maxPixelH,
		}, nil

	case 2: // Fit
		scaleW := float64(maxPixelW) / float64(srcW)
		scaleH := float64(maxPixelH) / float64(srcH)
		scale := math.Min(scaleW, scaleH)

		targetW = int(math.Round(float64(srcW) * scale))
		targetH = int(math.Round(float64(srcH) * scale))

	default:
		targetW = maxPixelW
		targetH = maxPixelH
	}

	scaledImg := scaleBilinear(src, targetW, targetH)

	return &ANSImage{
		img:           scaledImg,
		scaleMethod:   scaleMethod,
		ditheringMode: ditheringMode,
		matteColor:    matteColor,
		noBg:          noBg,
		width:         targetW,
		height:        targetH,
	}, nil
}

func blendColor(c color.Color, matte color.Color) (r, g, b uint8) {
	cr, cg, cb, ca := c.RGBA()
	if ca == 0xffff {
		return uint8(cr >> 8), uint8(cg >> 8), uint8(cb >> 8)
	}

	mr, mg, mb, _ := matte.RGBA()
	alpha := float64(ca) / 65535.0

	fr := (float64(cr) * alpha) + (float64(mr) * (1.0 - alpha))
	fg := (float64(cg) * alpha) + (float64(mg) * (1.0 - alpha))
