		}
		if srcY >= float64(srcH-1) {
			srcY = float64(srcH - 1)
		}
		y0 := int(srcY)
		y1 := y0 + 1
		if y1 >= srcH {
			y1 = srcH - 1
		}
		dy := srcY - float64(y0)

		for x := 0; x < width; x++ {
