			}
			sb.WriteString("\x1b[0m\n")

			line := sb.String()
			if isGo {
				goLine := strings.ReplaceAll(line, "\x1b", "\\033")
				fmt.Printf("fmt.Print(%q)\n", goLine)
			} else {
				fmt.Print(line)
			}
