		Col    uint16
		Xpixel uint16
		Ypixel uint16
	}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, errno
	}
	return int(ws.Col), int(ws.Row), nil
}

func isTerminal(fd uintptr) bool {
	var ws struct {
		Row    uint16
		Col    uint16
		Xpixel uint16
		Ypixel uint16
	}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	return errno == 0
}

func parseMatteColor(hexStr string) (colorful.Color, error) {
	s := hexStr
	if !strings.HasPrefix(s, "#") {
		s = "#" + s
	}
	return colorful.Hex(s)
}

func loadImage(path string) (image.Image, error) {
	if strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
		resp, err := http.Get(path)
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			return nil, fmt.Errorf("HTTP %s", resp.Status)
		}
		img, _, err := image.Decode(resp.Body)
		return img, err
	}

	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	img, _, err := image.Decode(f)
	return img, err
}

func main() {
	log.SetPrefix("[PIXTERM ERROR] ")
	log.SetFlags(log.LstdFlags)

	appName := filepath.Base(os.Args[0])

	var showVer bool
	var showCred bool
	var showHelp bool
	var ditheringMode int
	var scaleMethod int
	var matteStr string
	var noBg bool
	var goCode bool
	var termCols int
	var termRows int

	flagSet := flag.NewFlagSet(appName, flag.ContinueOnError)
	flagSet.Usage = func() {}

	flagSet.BoolVar(&showVer, "version", false, "")
	flagSet.BoolVar(&showCred, "credits", false, "")
	flagSet.BoolVar(&showHelp, "help", false, "")
	flagSet.BoolVar(&showHelp, "h", false, "")
	flagSet.IntVar(&ditheringMode, "d", 0, "")
	flagSet.IntVar(&scaleMethod, "s", 0, "")
	flagSet.StringVar(&matteStr, "m", "000000", "")
	flagSet.BoolVar(&noBg, "nobg", false, "")
	flagSet.BoolVar(&goCode, "go", false, "")
	flagSet.IntVar(&termCols, "tc", 0, "")
	flagSet.IntVar(&termRows, "tr", 0, "")

	err := flagSet.Parse(os.Args[1:])
	if err != nil {
		showUsage(appName)
		os.Exit(2)
	}

	if showVer {
		fmt.Println(version)
		os.Exit(0)
	}

	if showCred {
		fmt.Print(banner)
		fmt.Print(credits)
		os.Exit(0)
	}

	if showHelp {
		showUsage(appName)
		os.Exit(0)
	}

	if flagSet.NArg() != 1 {
		showUsage(appName)
		os.Exit(2)
	}

	// Validate options
	tcSet := false
	trSet := false
	flagSet.Visit(func(f *flag.Flag) {
		if f.Name == "tc" {
			tcSet = true
		}
		if f.Name == "tr" {
			trSet = true
		}
	})

	if (tcSet && termCols < 2) || (trSet && termRows < 2) || ditheringMode < 0 || ditheringMode > 2 || scaleMethod < 0 || scaleMethod > 2 {
		showUsage(appName)
		os.Exit(2)
	}

	// Determine terminal size
	stdoutFd := os.Stdout.Fd()
	isTTY := isTerminal(stdoutFd)

	if !tcSet {
		if isTTY {
			w, _, err := getTerminalSize(stdoutFd)
			if err == nil && w >= 2 {
				termCols = w
			} else {
				termCols = 80
			}
		} else {
			termCols = 80
		}
	}

	if !trSet {
		if isTTY {
			_, h, err := getTerminalSize(stdoutFd)
			if err == nil && h >= 2 {
				termRows = h - 2
				if termRows < 2 {
					termRows = 2
				}
			} else {
				termRows = 24
			}
		} else {
			termRows = 24
		}
	}

	matteColor, err := parseMatteColor(matteStr)
	if err != nil {
		fmt.Print(banner)
		log.Printf("matte color : %s is not a hex-color", matteStr)
		os.Exit(2)
	}

	imagePath := flagSet.Arg(0)
	img, err := loadImage(imagePath)
	if err != nil {
		fmt.Print(banner)
		log.Printf("%v", err)
		os.Exit(1)
	}

	ansImg, err := NewScaledFromImage(img, scaleMethod, termCols, termRows, matteColor, ditheringMode, noBg)
	if err != nil {
		fmt.Print(banner)
		log.Printf("%v", err)
		os.Exit(1)
	}

	if goCode {
		ansImg.RenderGo()
	} else {
		ansImg.Render()
	}
}
EOF"}

